package com.example.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="stage_sessions") public class StageSession { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long stageSessionId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="game_session_id", nullable=false) private GameSession gameSession; private int currentQuestionIndex; private int correctCount; private int enemyHp; private int combo; @Enumerated(EnumType.STRING) private StageSessionStatus status; private Instant startedAt; private Instant endedAt; private Instant pausedAt; private long totalPausedMs; public Long getStageSessionId() { return stageSessionId; } public void setStageSessionId(Long id) { this.stageSessionId = id; } public GameSession getGameSession() { return gameSession; } public void setGameSession(GameSession g) { this.gameSession = g; } public int getCurrentQuestionIndex() { return currentQuestionIndex; } public void setCurrentQuestionIndex(int c) { this.currentQuestionIndex = c; } public int getCorrectCount() { return correctCount; } public void setCorrectCount(int c) { this.correctCount = c; } public int getEnemyHp() { return enemyHp; } public void setEnemyHp(int e) { this.enemyHp = e; } public int getCombo() { return combo; } public void setCombo(int c) { this.combo = c; } public StageSessionStatus getStatus() { return status; } public void setStatus(StageSessionStatus s) { this.status = s; } public Instant getStartedAt() { return startedAt; } public void setStartedAt(Instant s) { this.startedAt = s; } public Instant getEndedAt() { return endedAt; } public void setEndedAt(Instant e) { this.endedAt = e; } public Instant getPausedAt() { return pausedAt; } public void setPausedAt(Instant p) { this.pausedAt = p; } public long getTotalPausedMs() { return totalPausedMs; } public void setTotalPausedMs(long t) { this.totalPausedMs = t; } }
